module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);parameter BUFFER_DEPTH = 8;
    reg [7:0] buffer [0:BUFFER_DEPTH-1];
    reg [3:0] count = 0;
    reg [9:0] accumulator = 0;
    reg [2:0] index = 0;
    reg [2:0] next_index = 0;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 0;
            accumulator <= 0;
            index <= 0;
            valid_b <= 0;
        end
        else begin
            if (valid_a && ready_b) begin
                buffer[index] <= data_in;
                count <= count + 1;
                accumulator <= accumulator + data_in;
                next_index <= index + 1;
                if (next_index == BUFFER_DEPTH) begin
                    next_index <= 0;
                end
                index <= next_index;
            end
            if (count == BUFFER_DEPTH) begin
                valid_b <= 1;
                data_out <= accumulator;
                accumulator <= 0;
                count <= 0;
            end
            else begin
                valid_b <= 0;
            end
        end
    end

    assign ready_a = ~valid_b;

endmodule

