module mealy_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter C=0, D=1, E=2, F=3;

    always_comb begin
        case (state)
            C: next_state = in1 ? D : E;
            D: next_state = in2 ? F : C;
            E: next_state = in1 ? F : C;
            F: next_state = in2 ? D : E;
        endcase
    end

    always_comb begin
        case (state)
            C: out = 1;
            D: out = 0;
            E: out = 1;
            F: out = 0;
        endcase
    end

endmodule

