    if (areset == 0) begin
        count_reg1 <= 4'b0;
        count_reg2 <= 4'b0;
        max_reached_reg1 <= 1'b0;
        max_reached_reg2 <= 1'b0;
    end else begin
        if (load) begin
            count_reg1 <= count_enable ? count : count_reg1;
            count_reg2 <= count_reg1;
            max_reached_reg1 <= (up_down && count_reg1 == 4'b1111) || (!up_down && count_reg1 == 4'b0000) ? 1'b1 : 1'b0;
            max_reached_reg2 <= max_reached_reg1;
