module top_module(
    input clk,
    input rst,
    input start,
    input [31:0] seed,
    output reg [31:0] rand_num,
    output reg done
);// LCG parameters
    parameter a = 1664525;
    parameter c = 1013904223;
    parameter m = 2**32;

    // Internal state variables
    reg [31:0] x;
    reg [31:0] next_x;
    reg [31:0] count;

    // Initialization
    always @ (posedge clk) begin
        if (rst) begin
            x <= seed;
            count <= 0;
        end else if (start) begin
            x <= seed;
            count <= 0;
        end else begin
            x <= next_x;
            count <= count + 1;
        end
    end

    // LCG
    always @ (posedge clk) begin
        if (start && count < 1000) begin
            next_x <= (a * x + c) % m;
            rand_num <= next_x;
        end else begin
            next_x <= x;
            rand_num <= 0;
            done <= 1;
        end
    end

endmodule

