module top_module(
    input clk,
    input reset,
    input [7:0] pulse_width,
    output reg pulse
);reg [7:0] counter;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 0;
            pulse <= 0;
        end else if (counter < pulse_width) begin
            counter <= counter + 1;
            pulse <= 1;
        end else begin
            counter <= 0;
            pulse <= 0;
        end
    end

endmodule

