description:
Design a clock divider that takes a primary clock input (CLK) and generates a slower clock output (sclk) by dividing the primary clock signal by 16. On a reset signal (RST), the divider will reset its counter to zero. The output sclk will toggle every 16 clock cycles, effectively creating a clock signal that is one-quarter of the input clock frequency.
module top_module(
    input CLK,    
    input RST,    
    output sclk   
    );

code:
module top_module(
    input CLK,    
    input RST,    
    output sclk   
    );reg [3:0] div;

    always @(posedge CLK or posedge RST)
    begin
        if (RST)
            div <= 1'b0;
        else
            div <= div + 1'b1;
    end

    assign sclk = div[3];

endmodule

