module top_module(Y, D0, D1, D2, D3, D4, D5, D6, D7, A, B, C);output [7:0] Y;
    input [7:0] D0, D1, D2, D3, D4, D5, D6, D7;
    input A, B, C;

    wire [7:0] Y0, Y1, Y2, Y3, Y4, Y5, Y6, Y7;

    // First level of 4-to-1 multiplexers
    assign Y0 = (A & B & C) ? D7 : (A & B & ~C) ? D6 : (A & ~B & C) ? D5 : (A & ~B & ~C) ? D4 : 8'b0;
    assign Y1 = (A & B & C) ? D5 : (A & B & ~C) ? D4 : (A & ~B & C) ? D3 : (A & ~B & ~C) ? D2 : 8'b0;
    assign Y2 = (A & B & C) ? D3 : (A & B & ~C) ? D2 : (A & ~B & C) ? D1 : (A & ~B & ~C) ? D0 : 8'b0;
    assign Y3 = (A & B & C) ? D1 : (A & B & ~C) ? D0 : (A & ~B & C) ? D7 : (A & ~B & ~C) ? D6 : 8'b0;
    assign Y4 = (~A & B & C) ? D7 : (~A & B & ~C) ? D6 : (~A & ~B & C) ? D5 : (~A & ~B & ~C) ? D4 : 8'b0;
    assign Y5 = (~A & B & C) ? D5 : (~A & B & ~C) ? D4 : (~A & ~B & C) ? D3 : (~A & ~B & ~C) ? D2 : 8'b0;
    assign Y6 = (~A & B & C) ? D3 : (~A & B & ~C) ? D2 : (~A & ~B & C) ? D1 : (~A & ~B & ~C) ? D0 : 8'b0;
    assign Y7 = (~A & B & C) ? D1 : (~A & B & ~C) ? D0 : (~A & ~B & C) ? D7 : (~A & ~B & ~C) ? D6 : 8'b0;

    // Second level of 2-to-1 multiplexers
    assign Y = (C) ? ((B) ? Y0 : Y1) : ((B) ? Y2 : Y3);
    assign Y = (A) ? ((B) ? Y4 : Y5) : ((B) ? Y6 : Y7);

