description:
Design a register file that supports reading and writing operations for a set of 32, 32-bit registers. The module allows simultaneous reading of two registers specified by `ReadRegisters1` and `ReadRegisters2`, where the outputs default to zero if the read addresses are zero. A write operation is conducted on the rising edge of the clock if the `RegWrite` signal is asserted, writing the `WriteData` into the register indicated by `WriteRegister`. This design is essential for maintaining state in a processor architecture, providing a means to store and retrieve data efficiently.
module top_module(ReadData1, ReadData2, clk, ReadRegisters1, ReadRegisters2, 
WriteRegister, RegWrite, WriteData);

code:
module top_module(ReadData1, ReadData2, clk, ReadRegisters1, ReadRegisters2, 
WriteRegister, RegWrite, WriteData);input clk;
    input [4:0] ReadRegisters1;
    input [4:0] ReadRegisters2;
    input [4:0] WriteRegister;
    input RegWrite;
    input [31:0] WriteData;

    output [31:0] ReadData1;
    output [31:0] ReadData2;

    reg [31:0] regs[31:0];
    assign ReadData1 = (ReadRegisters1 == 5'b0) ? 32'b0:regs[ReadRegisters1];
    assign ReadData2 = (ReadRegisters2 == 5'b0) ? 32'b0:regs[ReadRegisters2];
    always @(posedge clk)
    begin
        if (RegWrite) begin
            regs[WriteRegister] <= WriteData;
        end
    end
endmodule

