// Input h goes to two different two-input gates: a OR and a XOR gate. Each of the two gates is connected to the input of a D flip-flop and then the flip-flop outputs both go to a NOR gate, whose output is W. The second input of the OR is its corresponding flip-flop's output, and the second input of the XOR is its corresponding flip-flop's complemented output.
module fsm_module9 (
	input clk,
	input h,
	output w);

code:
module fsm_module9 (
	input clk,
	input h,
	output w);reg [1:0] state = 0;

	always @(posedge clk) begin
		state <= { (state[1] | h), (state[0] ^ h) };		
	end

	assign w = ~(state[1] | state[0]);

endmodule

