module top_module(input clk_50, input btn_in, output btn_out);reg  btn0 = 0;
    reg  btn1 = 0;
    reg  btn2 = 0;
    always@(posedge clk_50)
    begin
        btn0 <= btn_in;
        btn1 <= btn0;
        btn2 <= btn1;
    end

    assign btn_out = (btn2 & btn1 & btn0) | (~btn2 & btn1 & btn0);
endmodule

