module top_module (
        input clk,
        input areset,
        input x,
        output reg z);parameter Even=1'b0, Odd=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Even;
		else begin
			case (state)
				Even: state <= x ? Odd : Even;
				Odd: state <= x ? Even : Odd;
			endcase
		end
	end

	assign z = (state == Even && x==0) | (state == Odd && x==1);

endmodule

