description:
Design a clock divider circuit that scales down the frequency of an input clock signal (`clk_in`). The output clock signal (`clk_out`) toggles its state every 40 rising edges of the `clk_in`, effectively dividing the input clock frequency by 80. The circuit is also equipped with an active-low reset feature (`rst_n`) to initialize the output and the counter when asserted, ensuring reliable operation during reset conditions.
module top_module(
		input wire	clk_in,		
		input wire	rst_n,
		output reg	clk_out	
	);

code:
module top_module(
		input wire	clk_in,		
		input wire	rst_n,
		output reg	clk_out	
	);reg[5:0] cnt;


always @(posedge clk_in)
begin
	if(!rst_n)begin
		clk_out <= 1'b0;
		cnt <= 6'd0;
	end
	else begin
		if(cnt == 6'd39)begin
			clk_out <= !clk_out;
			cnt <= 6'd0;
		end
		else begin
			cnt <= cnt + 6'd1;
		end
	end
end

endmodule

