  input rst,
  input clk,
  output rst_n
);reg rst_sync;

  always @(posedge clk or negedge rst) begin
    if (rst == 0) begin
      rst_sync <= 0;
    end else begin
      rst_sync <= 1;
    end
  end

  assign rst_n = ~rst_sync;

endmodule

